  const w = ws.data;
  return (
    <Ctx.Provider value={{ workspace: w, reload: ws.reload }}>
      <div className="workspace">
        <nav aria-label="Delovni prostor" className="sidenav">
          <p className="ws-name">
            {w.name} <span className="badge">{ROLE_LABEL[w.role]}</span>
