      {page.error ? <Alert>{errorText(page.error)}</Alert> : null}
      {page.data && (
        <ul className="cards">
          {page.data.items.map((c) => (
            <li key={c.id}>
              <Link to={`/w/${workspace.id}/kontakti/${c.id}`}>{contactName(c)}</Link>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
