import { useCallback, useEffect, useState } from 'react';

/** Loads data on mount and whenever `deps` change; exposes reload. */
export function useLoad<T>(load: () => Promise<T>, deps: unknown[]) {
  const [data, setData] = useState<T | null>(null);
  };
}

/** The filter part only (for Export): no paging. */
export function filterOf(q: ContactQuery) {
  const { page: _page, size: _size, deleted: _deleted, ...filter } = q;
  void _page;
  void _size;
  void _deleted;
  return Object.fromEntries(
    Object.entries(filter).filter(([, v]) => v !== undefined && v !== '' && !(Array.isArray(v) && v.length === 0)),
  );
}
}

/** The Export file name from Content-Disposition, preferring the UTF-8 form. */
export function filenameOf(disposition: string): string {
  const utf8 = /filename\*=UTF-8''([^;]+)/i.exec(disposition);
  if (utf8) {
    try {
      return decodeURIComponent(utf8[1]);
    } catch {
      // fall back to the plain name
    }
  }
  const plain = /filename="([^"]+)"/.exec(disposition);
  return plain ? plain[1] : 'kontakti.xlsx';
}

export function httpApi(getToken: () => Promise<string | null>, base = ''): Api {
  async function call(method: string, path: string, body?: unknown): Promise<Response> {
    const token = await getToken();
    const headers: Record<string, string> = {};
    if (token) headers.Authorization = `Bearer ${token}`;
    if (body !== undefined) headers['Content-Type'] = 'application/json';
    const res = await fetch(base + path, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
